buggy.simple_imputer_constant_fill_value_casti:
import numpy as np
import warnings
from sklearn.impute import SimpleImputer

def record_array(a):
    a = np.asarray(a)
    return {
        'shape': a.shape,
        'dtype': str(a.dtype),
        'values': a.ravel()[:10].tolist(),
    }

def exc_info(e):
    return {'type': type(e).__name__, 'msg': str(e)[:300]}

out = {}

# Shared data
X_int = np.array([0, 0, 0, 1], dtype=np.int64).reshape(-1, 1)
X_multi_int = np.array([[1,2,3],[2,3,4]], dtype=np.int64)
X_float = np.array([[1,2,3],[2,3,4]], dtype=np.float64)
X_float32 = X_float.astype(np.float32)

# 1) float fill_value into int64
try:
    imputer = SimpleImputer(missing_values=0, fill_value=3.2, strategy='constant')
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter('always')
        res = imputer.fit_transform(X_int)
    out['case1_float_fill_into_int'] = {
        'result': record_array(res),
        'warnings': [str(ww.message)[:200] for ww in w],
    }
except Exception as e:
    out['case1_float_fill_into_int'] = {'exception': exc_info(e)}

# 2) nan fill_value into int64
try:
    imputer = SimpleImputer(missing_values=0, fill_value=np.nan, strategy='constant')
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter('always')
        res = imputer.fit_transform(X_int)
    out['case2_nan_fill_into_int'] = {
        'result': record_array(res),
        'warnings': [str(ww.message)[:200] for ww in w],
    }
except Exception as e:
    out['case2_nan_fill_into_int'] = {'exception': exc_info(e)}

# 3) fit-time invalid cast error message
try:
    imputer = SimpleImputer(strategy='constant', fill_value=1.5, missing_values=2)
    imputer.fit(X_multi_int)
    out['case3_fit_invalid_cast_msg'] = {'result': 'no_exception'}
except Exception as e:
    out['case3_fit_invalid_cast_msg'] = {'exception': exc_info(e)}

# 4) transform-time invalid cast error message
try:
    imputer = SimpleImputer(strategy='constant', fill_value=1.5, missing_values=2)
    imputer.fit(X_float)
    imputer.transform(X_multi_int)
    out['case4_transform_invalid_cast_msg'] = {'result': 'no_exception'}
except Exception as e:
    out['case4_transform_invalid_cast_msg'] = {'exception': exc_info(e)}

# 5) same-kind behavior: should not error; dtype should remain float32
try:
    vals = [np.float64(1.5), 1.5, 1]
    results = []
    for fv in vals:
        imputer = SimpleImputer(strategy='constant', fill_value=fv, missing_values=2)
        res = imputer.fit_transform(X_float32)
        results.append({'fill_value': str(fv), 'dtype': str(res.dtype)})
    out['case5_same_kind_float_fill_value_dtype'] = results
except Exception as e:
    out['case5_same_kind_float_fill_value_dtype'] = {'exception': exc_info(e)}

# 6) string fill_value error message
try:
    missing_value = -999.0
    X = np.array([[missing_value, 1.0], [2.0, 3.0]], dtype=np.float64)
    imputer = SimpleImputer(missing_values=missing_value, strategy='constant', fill_value='x')
    imputer.fit_transform(X)
    out['case6_string_fill_value_msg'] = {'result': 'no_exception'}
except Exception as e:
    out['case6_string_fill_value_msg'] = {'exception': exc_info(e)}

probe('out', out)

